/**
 * Preset learning content, loaded from the JSON files in /content.
 *
 * Those files are generated by tone-analysis/scripts/build_app_content.py
 * from the source spreadsheets. Every `tone` in them is computed by the
 * engine's own syllable_tone() at build time — nothing here parses tones or
 * hand-assigns them (and the import flags any sheet whose hand-entered tones
 * disagree).
 */
import toneTunerFile from "../../content/tone-tuner/items.json";
import foodFile from "../../content/vocab/food.json";
import colorsFile from "../../content/vocab/colors.json";
import bodyFile from "../../content/vocab/body.json";
import clothingFile from "../../content/vocab/clothing.json";
import homeFile from "../../content/vocab/home.json";

import { TONE_INFO, type ToneKey } from "./tones";

export type { ToneKey };

export type Syllable = { text: string; tone: ToneKey; mark_index: number };

export type ToneTunerItem = {
  id: string;
  text: string;
  meaning: string;
  kind: "word" | "phrase" | "sentence";
  glottalization_target: boolean;
  syllables: Syllable[];
  reference_audio: string | null;
};

export type VocabWord = {
  id: string;
  text: string;
  meaning: string;
  syllables: Syllable[];
  audio_file: string;
  audio: string | null;
  /** Who is speaking in `audio`: placeholder TTS until the native recordings replace it. */
  audio_source?: "google-tts" | "native";
  audio_voice?: string;
  image?: string;
  /** Twemoji codepoint the image came from (attribution: public/vocab/SOURCES.md). */
  twemoji?: string;
  swatch?: string;
};

export type VocabCollection = {
  id: string;
  title: string;
  words: VocabWord[];
  /** Sheet rows with no clear picture yet: never drilled, waiting for custom art. */
  left_out?: { text: string; meaning: string; reason: string }[];
};

/** Tone names (one source of truth: src/lib/tones.ts). */
export const TONE_LABELS: Record<ToneKey, { vi: string; en: string }> = TONE_INFO;

export const toneTunerItems = toneTunerFile.items as ToneTunerItem[];

export const vocabCollections: VocabCollection[] = [
  foodFile as VocabCollection,
  colorsFile as VocabCollection,
  bodyFile as VocabCollection,
  clothingFile as VocabCollection,
  homeFile as VocabCollection,
];

/** Vietnamese titles for the collections shown in the app. */
export const COLLECTION_TITLES: Record<string, string> = {
  food: "Thức ăn",
  colors: "Màu sắc",
  body: bodyFile.title_vi,
  clothing: clothingFile.title_vi,
  home: homeFile.title_vi,
};

export function getCollection(id: string): VocabCollection | undefined {
  return vocabCollections.find((c) => c.id === id);
}

/**
 * Every phrase the Tone Tuner may be asked to analyze. The server route
 * rejects anything else — preset content only, never free-typed text
 * (TAD 4.3, Decision 6).
 */
export const PRESET_TARGETS: ReadonlySet<string> = new Set([
  ...toneTunerItems.map((i) => i.text),
  ...vocabCollections.flatMap((c) => c.words.map((w) => w.text)),
]);
